126	// ValidateEmailSetting validates notification email SMTP settings.
127	func ValidateEmailSetting(setting *storepb.InstanceNotificationSetting_EmailSetting) error {
128		return EmailConfigFromInstanceSetting(setting).Validate()
129	}
130	
131	// SendTestEmail sends a plain-text test email using notification email settings.
132	func SendTestEmail(setting *storepb.InstanceNotificationSetting_EmailSetting, recipientEmail string) error {
133		return email.Send(EmailConfigFromInstanceSetting(setting), NewTestEmailMessage(recipientEmail, setting.GetReplyTo()))
134	}
